import { checkMultipleServices } from "./httpClient.js";
import { services } from "./services.js";

/**
 * Prepare service URLs for health checking
 * @returns {Array} - List of services with their URLs
 */
function prepareServiceChecks() {
  const serviceList = [];

  for (const service in services) {
    if (services.hasOwnProperty(service)) {
      serviceList.push({
        name: services[service].name,
        url: `${services[service].devUrl}/health`,
        timeout: 30000,
      });
    }
  }

  console.log(serviceList);

  return serviceList;
}

/**
 * Perform comprehensive health check of all services
 * @returns {Promise<{allHealthy: boolean, services: Object, timestamp: string}>}
 */
export async function performHealthCheck() {
  const servicesToCheck = prepareServiceChecks();
  const healthStatus = await checkMultipleServices(servicesToCheck);

  // Add gateway health
  const allServices = {
    gateway: {
      status: "up",
      details: {
        port: 3000,
        uptime: process.uptime(),
        memoryUsage: process.memoryUsage().rss,
      },
    },
    ...healthStatus,
  };

  const allHealthy = Object.values(allServices).every((service) => service.status === "up");

  return {
    allHealthy,
    services: allServices,
    timestamp: new Date().toISOString(),
  };
}

/**
 * Generate HTTP response based on health check results
 * @returns {Promise<{statusCode: number, body: Object}>}
 */
export async function getHealthResponse() {
  const healthData = await performHealthCheck();

  return {
    statusCode: healthData.allHealthy ? 200 : 503,
    body: {
      success: healthData.allHealthy,
      message: healthData.allHealthy
        ? "All services are operational"
        : "Some services are experiencing issues",
      timestamp: healthData.timestamp,
      services: healthData.services,
    },
  };
}

import axios from "axios";

/**
 * Make HTTP GET request to check service health
 * @param {string} url - Full URL to check
 * @param {number} timeout - Request timeout in milliseconds
 * @returns {Promise<{status: string, data?: any, error?: string}>}
 */
export async function checkServiceHealth(url, timeout = 3000) {
  try {
    const response = await axios.get(url, { timeout });
    return {
      status: "up",
      data: response.data,
      statusCode: response.status,
    };
  } catch (error) {
    let errorMessage = error.message;

    if (error.code === "ECONNREFUSED") {
      errorMessage = "Service not reachable";
    } else if (error.code === "ETIMEDOUT") {
      errorMessage = "Connection timeout";
    } else if (error.response) {
      errorMessage = `HTTP ${error.response.status}: ${error.response.statusText}`;
    }

    return {
      status: "down",
      error: errorMessage,
      statusCode: error.response?.status || null,
    };
  }
}

/**
 * Check multiple services in parallel
 * @param {Array<{url: string, timeout: number, name: string}>} services
 * @returns {Promise<Object>} - Map of service names to health status
 */
export async function checkMultipleServices(services) {
  const checks = services.map(async (service) => {
    const result = await checkServiceHealth(service.url, service.timeout);
    return { [service.name]: result };
  });

  const results = await Promise.all(checks);
  return Object.assign({}, ...results);
}

