import mongoose from "mongoose";

const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 5000;

export default async function connectDB(mongoUri, retries = MAX_RETRIES) {
  try {
    if (!mongoUri) {
      throw new Error("mongodb uri is required");
    }
    await mongoose.connect(mongoUri);
    console.log(`MongoDB connected: ${mongoose.connection.host}`);
  } catch (error) {
    if (retries > 0) {
      console.warn(
        `MongoDB connection failed, retrying in ${RETRY_DELAY_MS}ms... (${retries} retries left)`
      );
      await new Promise((res) => setTimeout(res, RETRY_DELAY_MS));
      return connectDB(mongoUri, retries - 1);
    }
    console.error("Could not connect to MongoDB. Exiting...");
    process.exit(1);
  }
}

const parseDurationToMs = (duration) => {
  const match = duration.match(/^(\d+)(ms|[smhdwyMY])$/);
  if (!match) throw new Error(`Invalid duration format: ${duration}`);

  const value = parseInt(match[1], 10);
  const unit = match[2];

  const multipliers = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000,
    M: 30 * 24 * 60 * 60 * 1000, // approximate
    y: 365 * 24 * 60 * 60 * 1000, // approximate
  };

  if (!multipliers[unit]) throw new Error(`Unknown unit: ${unit}`);
  return value * multipliers[unit];
};

