import clickService from "../services/click.service.js";
import geoip from "geoip-lite";
import { UAParser } from "ua-parser-js";
import rabbitmq from "../utils/rabbitMQ.js";

class ClickController {
  handleRecordClick = async (req, res, next) => {
    try {
      const slug = req.params.slug || req.body.slug;
      if (!slug) {
        throw new Error("Missing slug");
      }

      const { ip, userAgent, referrer } = req.body;

      if (!ip || !userAgent) {
        throw new Error("Missing required fields");
      }

      const click = await clickService.recordClick({
        slug,
        referrer,
        ip,
        userAgent,
      });

      if (!click) throw new Error("Failed to record click");

      res.status(201).json(click);
    } catch (error) {
      next(error);
    }
  };

  handleGetClicks = async (req, res, next) => {
    try {
      const { filter, pagination } = req.query;
      const clicks = await clickService.getClicks(filter, pagination);
      const count = await clickService.getClicksCount(filter);
      res.status(200).json({ clicks, count });
    } catch (error) {
      next(error);
    }
  };

  subscribeToClickEvents = () => {
    rabbitmq.subscribeToQueue("clicks", async (message) => {
      try {
        const clickData = JSON.parse(message);
        await clickService.recordClick(clickData);
      } catch (err) {
        console.error("Failed to process click event:", err);
      }
    });
  };
}

const clickController = new ClickController();
export default clickController;

import linkStatsService from "../services/linkStats.service.js";

export const getStats = async (req, res, next) => {
  try {
    const { slug } = req.params || req.query;
    const stats = await linkStatsService.getStats(slug);
    if (!stats) {
      return res.status(404).json({ success: false, message: "No stats found for this slug" });
    }
    res.status(200).json({ success: true, result: stats });
  } catch (error) {
    next(error);
  }
};

import { verifyAccessToken } from "../utils/token.js";
import { ACCESS_COOKIE_OPTIONS } from "../config/env.js";
import axios from "axios";

export const authMiddleware = async (req, res, next) => {
  try {
    const token = req.cookies.accessToken || req.headers.authorization?.replace("Bearer ", "");

    if (!token) {
      return res.status(401).json({ message: "Unauthorized - No token provided" });
    }

    try {
      const profileResponse = await axios.get("http://localhost:3001/api/profile", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      req.user = profileResponse.data.result;
      next();
    } catch (axiosError) {
      if (axiosError.response?.status === 401) {
        res.clearCookie("accessToken", ACCESS_COOKIE_OPTIONS);
        return res.status(401).json({
          message: "Invalid or expired token",
        });
      }

      console.error("User service error:", axiosError.message);
      return res.status(503).json({ message: "User service unavailable" });
    }
  } catch (error) {
    console.error("Authentication error:", error);
    res.status(500).json({ message: "Internal server error" });
  }
};

