import clickModel from "../models/click.model.js";
import linkStatsService from "./linkStats.service.js";
import geoip from "geoip-lite";
import { UAParser } from "ua-parser-js";

class ClickService {
  recordClick = async (clickData) => {
    console.log("Recording click: ", clickData);

    const geo = geoip.lookup(clickData.ip);

    if (geo) {
      console.log("GEO DATA: ", JSON.stringify(geo));
    }

    const parser = new UAParser(clickData.userAgent);
    const uaResult = parser.getResult();

    clickData.country = geo?.country;
    clickData.city = geo?.city;
    clickData.deviceType = uaResult.device?.model;
    clickData.browser = uaResult.browser?.name;
    clickData.os = uaResult.os?.name;

    const click = await clickModel.create(clickData);
    if (!click) throw new Error("Failed to record click");

    // Update aggregated stats asynchronously (do not block the response)
    linkStatsService
      .updateStats(click.slug, click)
      .catch((err) => console.error("Stats update failed:", err));

    return click;
  };

  getClicks = async (filter = {}, pagination = {}) => {
    const clicks = await clickModel
      .find(filter)
      .skip(pagination.skip || 0)
      .limit(pagination.limit || 50)
      .sort({ timestamp: -1 });
    return clicks;
  };

  getClicksCount = async (filter = {}) => {
    return await clickModel.countDocuments(filter);
  };
}

const clickService = new ClickService();
export default clickService;

import LinkStats from "../models/linkStats.model.js";

class LinkStatsService {
  /**
   * Atomically update aggregated stats for a slug.
   * Uses MongoDB aggregation pipeline in the update to handle
   * daily clicks, top referrers, top countries, etc.
   */
  async updateStats(slug, click) {
    const today = new Date().toISOString().slice(0, 10); // "YYYY-MM-DD"
    const deviceField = click.deviceType === "mobile" ? "mobile"
                      : click.deviceType === "tablet" ? "tablet"
                      : "desktop";
    const browserName = click.browser || "Other";
    const osName = click.os || "Other";
    const referrer = click.referrer || "direct";
    const country = click.country || "Unknown";

    await LinkStats.findOneAndUpdate(
      { slug },
      [
        {
          $set: {
            totalClicks: { $add: [{ $ifNull: ["$totalClicks", 0] }, 1] },
            // Daily clicks: increment existing entry or push new one
            dailyClicks: {
              $cond: {
                if: { $in: [today, { $ifNull: ["$dailyClicks.date", []] }] },
                then: {
                  $map: {
                    input: { $ifNull: ["$dailyClicks", []] },
                    as: "dc",
                    in: {
                      date: "$$dc.date",
                      count: { $cond: [{ $eq: ["$$dc.date", today] }, { $add: ["$$dc.count", 1] }, "$$dc.count"] }
                    }
                  }
                },
                else: { $concatArrays: [{ $ifNull: ["$dailyClicks", []] }, [{ date: today, count: 1 }]] }
              }
            },
            // Top referrers: increment or push, then keep top 10
            topReferrers: this._updateTopArray("$topReferrers", referrer),
            // Top countries: same logic
            topCountries: this._updateTopArray("$topCountries", country),
            // Devices, browsers, OSs – use $inc on nested paths
            [`devices.${deviceField}`]: { $add: [{ $ifNull: [`$devices.${deviceField}`, 0] }, 1] },
            [`browsers.${browserName}`]: { $add: [{ $ifNull: [`$browsers.${browserName}`, 0] }, 1] },
            [`operatingSystems.${osName}`]: { $add: [{ $ifNull: [`$operatingSystems.${osName}`, 0] }, 1] },
            lastUpdated: new Date(),
          }
        }
      ],
      {
        returnDocument: 'after',
        upsert: true,
        updatePipeline: true,
      }
    );
  }

  /**
   * Returns a pipeline expression that updates a top‑N array.
   * If the referrer/country already exists, increment its count;
   * otherwise push a new entry. Then sort by count descending,
   * slice to keep only the top 10, and sort back for storage.
   */
  _updateTopArray(fieldExpr, newValue) {
    return {
      $slice: [
        {
          $sortArray: {
            input: {
              $cond: {
                if: { $in: [newValue, { $ifNull: [`${fieldExpr}.referrer`, []] }] },
                then: {
                  $map: {
                    input: { $ifNull: [fieldExpr, []] },
                    as: "item",
                    in: {
                      referrer: "$$item.referrer",
                      count: {
                        $cond: [{ $eq: ["$$item.referrer", newValue] },
                          { $add: ["$$item.count", 1] },
                          "$$item.count"
                        ]
                      }
                    }
                  }
                },
                else: { $concatArrays: [{ $ifNull: [fieldExpr, []] }, [{ referrer: newValue, count: 1 }]] }
              }
            },
            sortBy: { count: -1 }
          }
        },
        10
      ]
    };
  }

  async getStats(slug) {
    const stats = await LinkStats.findOne({ slug });
    return stats;
  }
}

const linkStatsService = new LinkStatsService();
export default linkStatsService;

import amqp from "amqplib";

const RABBITMQ_URL = process.env.RABBITMQ_URL;
if (!RABBITMQ_URL) throw new Error("RABBITMQ_URL is required");

let connection = null;
let channel = null;

const connect = async () => {
  if (channel) return channel;

  connection = await amqp.connect(RABBITMQ_URL);
  channel = await connection.createChannel();

  connection.on("error", (err) => {
    console.error("[RabbitMQ] connection error:", err.message);
    connection = null;
    channel = null;
  });

  // Reconnect automatically when the broker closes the connection
  connection.on("close", () => {
    console.warn("[RabbitMQ] connection closed — reconnecting in 5s");
    connection = null;
    channel = null;
    setTimeout(connect, 5000);
  });

  console.log("[RabbitMQ] connected");
  return channel;
};

/**
 * Publish a message to a durable queue.
 * The message is persisted so it survives a broker restart.
 */
const publishToQueue = async (queue, message) => {
  const ch = await connect();
  await ch.assertQueue(queue, { durable: true });
  ch.sendToQueue(queue, Buffer.from(JSON.stringify(message)), { persistent: true });
};

/**
 * Subscribe to a durable queue.
 * handler(parsedMessage) is called for each message.
 * Messages are ack'd on success or nack'd (no requeue) on handler error.
 */
const subscribeToQueue = async (queue, handler) => {
  const ch = await connect();
  await ch.assertQueue(queue, { durable: true });
  ch.prefetch(1); // process one message at a time per consumer
  ch.consume(queue, async (msg) => {
    if (!msg) return;
    try {
      const content = JSON.parse(msg.content.toString());
      await handler(content);
      ch.ack(msg);
    } catch (err) {
      console.error("[RabbitMQ] handler error:", err.message);
      ch.nack(msg, false, false); // discard — route to dead-letter if configured
    }
  });
};

export default { connect, publishToQueue, subscribeToQueue };

