    if (!user) {
      throw new Error("Invalid email or password");
    }

    // Check password
    const isMatch = await user.comparePassword(password);
    if (!isMatch) {
      throw new Error("Invalid email or password");
    }

    const accessToken = await generateAccessToken(user);

    console.log(`User logged in: ${email}`);

